    int mid = -1, depth = 0;
    for (int i = 0; i < (int)line.size(); ++i) {
        if (line[i] == '[') depth++;
        else if (line[i] == ']') {
            depth--;
            if (depth == 1) { mid = i; break; }
        }
    }
    auto parseVec = [](string s) {
        vector<int> res;
        for (char& c : s) if (c == '[' || c == ']' || c == ',') c = ' ';
        stringstream ss(s);
        int val;
        while (ss >> val) res.push_back(val);
        return res;
    };
